<script setup lang="ts">
import { IonButton, IonModal, IonSpinner, IonTextarea, IonToast } from '@ionic/vue'
import { ref } from 'vue'
import MyCheckbox from '@/components/MyCheckbox.vue'
import { problemCategoryOptions, useFeedback } from '@/composables/useFeedback'
import CheckLineIcon from '@/components/svg/CheckLineIcon.vue'

interface Props {
  isOpen: boolean
  universeId?: number
}

interface Emits {
  (e: 'close'): void
}

const props = defineProps<Props>()
const emit = defineEmits<Emits>()

const { problemCategory, problemDetail, feedback, feedbackState, feedbackInputIsValid } = useFeedback()
const toastIsOpen = ref(false)

function closeModal() {
  emit('close')
}

function handleSubmitClick() {
  if (feedbackInputIsValid.value === false) {
    toastIsOpen.value = true
    return
  }
  feedback(props.universeId ?? 0)
}
</script>

<template>
  <ion-modal
    :is-open="isOpen"
    :backdrop-dismiss="true"
    :initial-breakpoint="0.70"
    class="custom-ion-modal"
    @did-dismiss="closeModal"
  >
    <div class="relative flex flex-col h-[70%] bg-[#292929]">
      <ion-toast
        :is-open="toastIsOpen"
        :message="$t('feedbackModal.inputIsInvalid')"
        :duration="3000"
        position="middle"
        class="custom-toast"
        @did-dismiss="() => toastIsOpen = false"
      />
      <div class="flex-shrink-0 py-2 px-0.5 flex justify-between items-center">
        <ion-button fill="clear" size="small" class="text-on-bg-1 text-4 fw-500 leading-5" @click="() => { emit('close') }">
          {{ $t('feedbackModal.cancel') }}
        </ion-button>
        <p class="text-on-bg-1 text-4.5 fw-700 leading-5">
          {{ $t('feedbackModal.title') }}
        </p>
        <div class="w-16 h-6 flex-shrink-0" />
      </div>
      <div class="flex-1 overflow-scroll px-4 pt-0.5 pb-unsafe-area">
        <p class="text-on-bg-2 text-3.5 fw-400 leading-4.5">
          {{ $t('feedbackModal.selectAProblem') }}
        </p>
        <ul class="flex flex-col gap-4 py-4">
          <li
            v-for="opt in problemCategoryOptions" :key="opt"
            class="flex items-center gap-1.5"
            @click="() => { problemCategory = opt }"
          >
            <my-checkbox :model-value="opt === problemCategory" />
            <p class="text-on-bg-1 text-4 fw-400 leading-5">
              {{ $t(`feedbackModal.problemCategory.${opt}`) }}
            </p>
          </li>
        </ul>
        <div class="rounded-4 bg-[#3a3a3a] p-4 flex flex-col gap-2">
          <p class="text-on-bg-1 fw-500">
            {{ $t('feedbackModal.otherProblems') }}
          </p>
          <ion-textarea
            v-model="problemDetail"
            :placeholder="$t('feedbackModal.otherProblemsPlaceholder')"
            :rows="3"
            :auto-grow="true"
            class="rounded-2 bg-[#424242] px-3"
          />
        </div>
        <div class="w-full h-24" />
      </div>
      <div class="absolute z-2 bottom-10 left-[50%] translate-x-[-50%]">
        <button v-if="feedbackState === 'waitRes'" class="btn-primary min-w-36" @click="handleSubmitClick">
          <div class="flex items-center gap-1">
            <ion-spinner color="dark" />
            <p>{{ $t('feedbackModal.submitting') }}</p>
          </div>
        </button>
        <button v-else-if="feedbackState === 'success'" class="btn-primary min-w-36">
          <div class="pt-2">
            <check-line-icon width="36" height="36" />
          </div>
        </button>
        <button v-else class="btn-primary min-w-36" @click="handleSubmitClick">
          <p>
            {{ $t('feedbackModal.submit') }}
          </p>
        </button>
      </div>
    </div>
  </ion-modal>
</template>

<style scoped>
ion-modal.custom-ion-modal {
  --border-radius: 16px;
}
</style>
