import { computed, ref } from 'vue'
import { useFetchState } from './useFetchState'
import { feedbackService } from '@/services/feedback'

export const problemCategoryOptions = ['ILLOGICAL', 'BORING', 'NOT_TRUE', 'HARMFUL', 'REPETITIVE', 'BAD_MEMORY', 'TOO_LONG'] as const
export type ProblemCategory = typeof problemCategoryOptions[number]

export function useFeedback() {
  const problemCategory = ref<ProblemCategory>()
  const problemDetail = ref('')
  const { fetchState } = useFetchState()

  const feedbackInputIsValid = computed(() => !(problemCategory.value === undefined && problemDetail.value === ''))

  async function feedback(universeId: number) {
    try {
      fetchState.value = 'waitRes'
      const { feedbackId } = await feedbackService.feedback({
        universeId,
        problemCategory: problemCategory.value ?? '',
        problemDetail: problemDetail.value,
      })
      console.log(`[feedback] success, feedbackId = ${feedbackId}`)
      fetchState.value = 'success'
    }
    catch (error) {
      fetchState.value = 'failed'
      console.log(`[feedback] error, ${JSON.stringify(error, null, 2)}`)
    }
  }

  return {
    problemCategory,
    problemDetail,
    feedback,
    feedbackState: fetchState,
    feedbackInputIsValid,
  }
}
