<script setup lang="ts">
import { IonCheckbox, IonContent, IonInput, IonPage } from '@ionic/vue'
import { useI18n } from 'vue-i18n'
import { computed, ref } from 'vue'
import RightArrowIcon from '@/components/svg/RightArrowIcon.vue'
import HeaderWithReturn from '@/components/HeaderWithReturn.vue'
import { useUserStore } from '@/store/user'
import { localeConfig } from '@/locales/config'
import type { LoginType } from '@/types'
import AuthModal from '@/components/AuthModal.vue'
import FeedbackModal from '@/components/FeedbackModal.vue'
import { useDebugStore } from '@/store/debug'

const { t } = useI18n()

const gitHash = `${import.meta.env.VITE_GIT_COMMIT_HASH}`

const userStore = useUserStore()
const debugStore = useDebugStore()

const authModalIsOpen = ref(false)
const feedbackModalIsOpen = ref(false)

const supportItems = computed(() => [
  { label: t('settingsPage.emailSupport'), href: `mailto:${localeConfig.customerSupportEmail}?subject=Feedback`, target: '_self' },
  { label: t('settingsPage.privacyPolicy'), href: localeConfig.links.privacyPolicy, target: '_blank' },
  { label: t('settingsPage.termsOfService'), href: localeConfig.links.termsOfService, target: '_blank' },
])

const envType = `MODE = ${import.meta.env.VITE_APP_ENV_TYPE}`

async function handleLogin(type: LoginType) {
  await userStore.logIn(type)
  authModalIsOpen.value = false
}

function handleFeedbackBtnClick() {
  if (userStore.isLoggedIn) {
    feedbackModalIsOpen.value = true
  }
  else {
    authModalIsOpen.value = true
  }
}
const date = new Date()
if (date.getTime() - debugStore.lastTime > debugStore.interval) {
  debugStore.lastTime = 0
}
function handleVersion() {
  if (debugStore.count === 0) {
    debugStore.count++
    debugStore.lastTime = date.getTime()
    return
  };
  const currentInterval = date.getTime() - debugStore.lastTime
  if (currentInterval < debugStore.interval) {
    if (debugStore.count >= debugStore.maxCount) {
      return
    };
    debugStore.count++
    debugStore.lastTime = date.getTime()
    return
  };
}
</script>

<template>
  <ion-page>
    <auth-modal
      :is-open="authModalIsOpen"
      :login-state="userStore.loginState"
      @close="() => authModalIsOpen = false"
      @click:continue-with-apple="handleLogin('apple')"
      @click:continue-with-google="handleLogin('google')"
    />
    <feedback-modal
      :is-open="feedbackModalIsOpen"
      @close="() => { feedbackModalIsOpen = false }"
    />
    <header-with-return :title="$t('settingsPage.title')" />
    <ion-content>
      <div class="flex flex-col gap-4 px-4 pt-4 pb-unsafe-area">
        <div v-if="userStore.isLoggedIn" class="rounded-4 bg-[#292929] pl-4 pr-2 py-3 flex items-center justify-between">
          <div>
            <p class="text-4 fw-600 leading-6">
              @{{ userStore.user.userId }}
            </p>
            <p class="text-on-bg-3 text-3.5 fw-500 leading-5">
              {{ $t('settingsPage.userId') }}
            </p>
          </div>
        </div>
        <ul class="rounded-4 bg-[#292929] px-4 py-2 flex flex-col gap-4">
          <li class="flex py-2" @click="handleFeedbackBtnClick">
            <div class="flex-1 flex items-center justify-between">
              <p class=" text-on-bg-1 text-4 fw-600 leading-6">
                {{ $t('settingsPage.feedback') }}
              </p>
              <right-arrow-icon />
            </div>
          </li>
          <li
            v-for="item in supportItems" :key="item.label"
            class="flex py-2"
          >
            <a
              :href="item.href" :target="item.target"
              class="flex-1 flex items-center justify-between"
            >
              <p class=" text-on-bg-1 text-4 fw-600 leading-6">{{ item.label }}</p>
              <right-arrow-icon />
            </a>
          </li>
          <router-link v-if="userStore.isLoggedIn" to="/delete-account" class="flex py-2">
            <div class="flex-1 flex items-center justify-between">
              <p class=" text-on-bg-1 text-4 fw-600 leading-6">
                {{ $t('settingsPage.deleteAccount') }}
              </p>
              <right-arrow-icon />
            </div>
          </router-link>
        </ul>
        <button v-if="userStore.isLoggedIn" class="bg-[#292929] rounded-full px-4 py-3 text-[#BDBDBD] text-4 fw-700 leading-6" @click="userStore.logOut">
          {{ $t('settingsPage.logout') }}
        </button>
        <button v-else class="bg-[#292929] rounded-full px-4 py-3 text-[#BDBDBD] text-4 fw-700 leading-6" @click="authModalIsOpen = true">
          {{ $t('settingsPage.login') }}
        </button>
        <p class="text-on-bg-3 text-3.5 fw-500 leading-4 text-center" @click="handleVersion">
          {{ `${$t('settingsPage.version')}:  ${gitHash}` }}
        </p>
        <p v-if="debugStore.isDebug">
          {{ envType }}
        </p>
        <ion-checkbox
          v-if="debugStore.isDebug"
          :checked="debugStore.enableVoice"
          @ion-change="(e) => {
            debugStore.setEnableVoice(e.detail.checked)
          }"
        >
          enable voice
        </ion-checkbox>
        <ion-checkbox
          v-if="debugStore.isDebug"
          :checked="debugStore.storyTellerMode"
          @ion-change="(e) => {
            debugStore.storyTellerMode = e.detail.checked
          }"
        >
          Storyteller Mode
        </ion-checkbox>
        <ion-input
          v-if="debugStore.isDebug"
          class="rounded-2 px-4 py-1 bg-input-bg-2"
          :value="debugStore.streamSpeed"
          type="number"
          @ion-change="(e) => {
            debugStore.streamSpeed = +(e.target.value || 30)
          }"
        >
          Stream Speed / Char (ms)
        </ion-input>
        <ion-input
          v-if="debugStore.isDebug"
          class="rounded-2 px-4 py-1 bg-input-bg-2"
          :value="debugStore.firstNarrationStreamSpeed"
          type="number"
          @ion-change="(e) => {
            debugStore.firstNarrationStreamSpeed = +(e.target.value || 20)
          }"
        >
          Stream Speed / Char (ms) (First Narration)
        </ion-input>
      </div>
    </ion-content>
  </ion-page>
</template>
